function validate(input) {
  const [{ Customer = [] }] = input;
  const visits = new Set(), days = new Set();
  for (const [id, , day, amount] of Customer) {
    if (id === null || day === null) return 'Every visit needs a customer_id and a visited_on.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || Number.isNaN(Date.parse(`${day}T00:00:00Z`))) return `${day} is not a date.`;
    if (amount === null) return `Customer ${id} on ${day} needs an amount.`;
    const key = `${id}:${day}`;
    if (visits.has(key)) return `(${id}, ${day}) appears twice in Customer.`;
    visits.add(key);
    days.add(day);
  }
  const sorted = [...days].sort();
  for (let i = 1; i < sorted.length; i++) {
    if (Date.parse(`${sorted[i]}T00:00:00Z`) - Date.parse(`${sorted[i - 1]}T00:00:00Z`) !== 86400000) return `No visit between ${sorted[i - 1]} and ${sorted[i]}.`;
  }
  return null;
}

