function generate(rand, size) {
  const small = size === 'small';
  const starts = ['2019-01-01', '2019-12-28', '2020-02-25', '2021-02-24'];
  const names = ['Jhon', 'Daniel', 'Jade', 'Khaled', 'Winston', 'Elvis', 'Anna', 'Maria', 'Jaze'];
  const start = Date.parse(`${starts[Math.floor(rand() * starts.length)]}T00:00:00Z`);
  const day = i => new Date(start + i * 86400000).toISOString().slice(0, 10);
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const dayCount = rows === 0 ? 0 : small ? 1 + Math.floor(rand() * rows) : 700;
  const customers = small ? 6 : 400;
  // Each date gets one visit; the remaining visits land on random dates, at most once per customer and date.
  const perDay = Array.from({ length: dayCount }, () => new Set());
  const Customer = [];
  const visit = d => {
    for (let tries = 0; tries < 20; tries++) {
      const id = 1 + Math.floor(rand() * customers);
      if (perDay[d].has(id)) continue;
      perDay[d].add(id);
      Customer.push([id, names[id % names.length], day(d), small ? 10 * Math.floor(rand() * 16) : Math.floor(rand() * 500)]);
      return;
    }
  };
  for (let d = 0; d < dayCount; d++) visit(d);
  for (let tries = 0; Customer.length < rows && tries < rows * 4; tries++) visit(Math.floor(rand() * dayCount));
  return [{ Customer }];
}
